fn preview_source_skeleton(
    records: &[engine::asset::SkeletonRecord],
    imported_animation_skeleton: Option<&AssetId>,
) -> Option<AssetId> {
    if let Some(imported_animation_skeleton) = imported_animation_skeleton
        && records
            .iter()
            .any(|record| record.id == imported_animation_skeleton.as_str())
    {
        return Some(imported_animation_skeleton.clone());
    }
    (records.len() == 1)
        .then(|| &records[0].id)
        .and_then(|id| AssetId::from_stable_id(engine_authoring::StableId::new(id)).ok())
}

